import AVFoundation

/// Short sound effects from Resources/SFX (generated by scripts/sfx.sh). They mix with the user's music,
/// stay quiet when the silent switch is on, and a missing file just means silence.
@MainActor
enum SFX: String {
    case tap, select, giftAppear = "gift-appear", giftOpen = "gift-open", reveal, success, error

    private static var players: [SFX: AVAudioPlayer] = [:]
    private static var sessionReady = false

    func play(volume: Float = 1) {
        if !Self.sessionReady {
            try? AVAudioSession.sharedInstance().setCategory(.ambient, options: [.mixWithOthers])
            Self.sessionReady = true
        }
        let player: AVAudioPlayer
        if let cached = Self.players[self] {
            player = cached
        } else {
            guard let url = Bundle.main.url(forResource: rawValue, withExtension: "m4a"),
                  let p = try? AVAudioPlayer(contentsOf: url) else { return }
            p.prepareToPlay()
            Self.players[self] = p
            player = p
        }
        player.volume = volume
        player.currentTime = 0
        player.play()
    }
}
